window.BOOK={"key":"thana","app":"mutoon-thana","lsk":"mutoon_thana_v1","prefix":"th_","title":"الثناء على الله","sub":"مختارات · من أمية بن أبي الصلت ولبيد إلى ابن القيم · ١٨٧ بيتًا","poems":[{"id":"thana","title":"الثناء على الله","nazim":"مختارات من عدة شعراء","death":"","meter":"الطويل والوافر والكامل والبسيط والمتقارب والخفيف والمنسرح والرمل ومجزوء الرجز","source":"البداية والنهاية لابن كثير (ت التركي) وسيرة ابن هشام ونونية ابن القيم (ط عطاءات العلم) ودواوين الشعراء (موقع الديوان)، مع «تعظيم الله جل جلاله: تأملات وقصائد» لأحمد المزيد","srcUrl":"https://shamela.ws/book/4445","note":"أشهر وأقوى أبيات الثناء على الله من كل قصيدة، في ستة أبواب: الحمد والتمجيد، التوحيد ودلائل القدرة، الأسماء والصفات، الآلاء والنعم، المناجاة والافتقار، الرجاء وحسن الظن. من شعر أمية بن أبي الصلت وزيد بن عمرو بن نفيل ولبيد والنابغة الجعدي وحسان وابن رواحة وأبي العتاهية وأبي نواس ومحمود الوراق والشافعي وابن تيمية وابن القيم وغيرهم. كل مقطوعة منقولة من مصدر منشور وقوبلت كلمةً كلمةً بسكربت بمصدر ثانٍ وفُحص وزن كل شطر. ما ضعفت نسبته كُتب «المنسوب إلى…». أبيات ابن تيمية والبرعي أُكمل شكلها يدويًّا لعدم وجود نشرة رقمية تامة الشكل، والتفصيل في تقرير المصادر (thana-sources.md).","verses":[["لَكَ الْحَمْدُ وَالنَّعْمَاءُ وَالْمُلْكُ رَبَّنَا","فَلَا شَيْءَ أَعْلَى مِنْكَ مَجْدًا وَأَمْجَدُ"],["مَلِيكٌ عَلَى عَرْشِ السَّمَاءِ مُهَيْمِنٌ","لِعِزَّتِهِ تَعْنُو الْوُجُوهُ وَتَسْجُدُ"],["عَلَيْهِ حِجَابُ النُّورِ وَالنُّورُ حَوْلَهُ","وَأَنْهَارُ نُورٍ حَوْلَهُ تَتَوَقَّدُ"],["فَلَا بَصَرٌ يَسْمُو إِلَيْهِ بِطَرْفِهِ","وَدُونَ حِجَابِ النُّورِ خَلْقٌ مُؤَيَّدُ"],["فَسَاجِدُهُمْ لَا يَرْفَعُ الدَّهْرَ رَأْسَهُ","يُعَظِّمُ رَبًّا فَوْقَهُ وَيُمَجِّدُ"],["فَسُبْحَانَ مَنْ لَا يَعْرِفُ الْخَلْقُ قَدْرَهُ","وَمَنْ هُوَ فَوْقَ الْعَرْشِ فَرْدٌ مُوَحَّدُ"],["وَمَنْ لَمْ تُنَازِعْهُ الْخَلَائِقُ مُلْكَهُ","وَإِنْ لَمْ تُفَرِّدْهُ الْعِبَادُ فَمُفْرَدُ"],["مَلِيكُ السَّمَوَاتِ الشِّدَادِ وَأَرْضِهَا","وَلَيْسَ بِشَيْءٍ عَنْ قَضَاهُ تَأَوُّدُ"],["هُوَ اللَّهُ بَارِي الْخَلْقِ وَالْخَلْقُ كُلُّهُمْ","إِمَاءٌ لَهُ طَوْعًا جَمِيعًا وَأَعْبُدُ"],["وَأَنَّى يَكُونُ الْخَلْقُ كَالْخَالِقِ الَّذِي","يَدُومُ وَيَبْقَى وَالْخَلِيقَةُ تَنْفَدُ"],["تُسَبِّحُهُ الطَّيْرُ الْجَوَانِحُ فِي الْخَفَى","وَإِذْ هِيَ فِي جَوِّ السَّمَاءِ تُصَعِّدُ"],["وَمِنْ خَوْفِ رَبِّي سَبَّحَ الرَّعْدُ فَوْقَنَا","وَسَبَّحَهُ الْأَشْجَارُ وَالْوَحْشُ أُبَّدُ"],["مَجِّدُوا اللَّهَ فَهْوَ لِلْمَجْدِ أَهْلٌ","رَبُّنَا فِي السَّمَاءِ أَمْسَى كَبِيرَا"],["بِالْبِنَاءِ الْأَعْلَى الَّذِي سَبَقَ النَّـ","ـاسَ وَسَوَّى فَوْقَ السَّمَاءِ سَرِيرَا"],["شَرْجَعًا لَا يَنَالُهُ بَصَرُ الْعَيْـ","ـنِ تَرَى دُونَهُ الْمَلَائِكَ صُورَا"],["إِلَى اللَّهِ أُهْدِي مِدْحَتِي وَثَنَائِيَا","وَقَوْلًا رَصِينًا لَا يَنِي الدَّهْرَ بَاقِيَا"],["إِلَى الْمَلِكِ الْأَعْلَى الَّذِي لَيْسَ فَوْقَهُ","إِلَهٌ وَلَا رَبٌّ يَكُونُ مُدَانِيَا"],["أَلَا أَيُّهَا الْإِنْسَانُ إِيَّاكَ وَالرَّدَى","فَإِنَّكَ لَا تُخْفِي مِنَ اللَّهِ خَافِيَا"],["وَإِيَّاكَ لَا تَجْعَلْ مَعَ اللَّهِ غَيْرَهُ","فَإِنَّ سَبِيلَ الرُّشْدِ أَصْبَحَ بَادِيَا"],["رَضِيتُ بِكَ اللَّهُمَّ رَبًّا فَلَنْ أُرَى","أَدِينُ إِلَهًا غَيْرَكَ اللَّهُ ثَانِيَا"],["وَأَنْتَ الَّذِي مِنْ فَضْلِ مَنٍّ وَرَحْمَةٍ","بَعَثْتَ إِلَى مُوسَى رَسُولًا مُنَادِيَا"],["فَقُلْتَ لَهُ يَا اذْهَبْ وَهَارُونَ فَادْعُوَا","إِلَى اللَّهِ فِرْعَوْنَ الَّذِي كَانَ طَاغِيَا"],["وَقُولَا لَهُ أَأَنْتَ سَوَّيْتَ هَذِهِ","بِلَا وَتَدٍ حَتَّى اطْمَأَنَّتْ كَمَا هِيَا"],["وَقُولَا لَهُ أَأَنْتَ رَفَّعْتَ هَذِهِ","بِلَا عَمَدٍ أَرْفِقْ إِذًا بِكَ بَانِيَا"],["وَقُولَا لَهُ أَأَنْتَ سَوَّيْتَ وَسْطَهَا","مُنِيرًا إِذَا مَا جَنَّهُ اللَّيْلُ هَادِيَا"],["وَقُولَا لَهُ مَنْ يُرْسِلُ الشَّمْسَ غُدْوَةً","فَيُصْبِحُ مَا مَسَّتْ مِنَ الْأَرْضِ ضَاحِيَا"],["وَقُولَا لَهُ مَنْ يُنْبِتُ الْحَبَّ فِي الثَّرَى","فَيُصْبِحُ مِنْهُ الْبَقْلُ يَهْتَزُّ رَابِيَا"],["وَيُخْرِجُ مِنْهُ حَبَّهُ فِي رُءُوسِهِ","وَفِي ذَاكَ آيَاتٌ لِمَنْ كَانَ وَاعِيَا"],["لَا تَعْبُدُنَّ إِلَهًا غَيْرَ خَالِقِكُمْ","فَإِنْ دَعَوْكُمْ فَقُولُوا بَيْنَنَا حَدَدُ"],["سُبْحَانَ ذِي الْعَرْشِ سُبْحَانًا يَدُومُ لَهُ","وَقَبْلَنَا سَبَّحَ الْجُودِيُّ وَالْجُمُدُ"],["مُسَخَّرٌ كُلُّ مَا تَحْتَ السَّمَاءِ لَهُ","لَا يَنْبَغِي أَنْ يُنَاوِي مُلْكَهُ أَحَدُ"],["لَا شَيْءَ مِمَّا نَرَى تَبْقَى بَشَاشَتُهُ","يَبْقَى الْإِلَهُ وَيُودِي الْمَالُ وَالْوَلَدُ"],["الْحَمْدُ لِلَّهِ لَا شَرِيكَ لَهُ","مَنْ لَمْ يَقُلْهَا فَنَفْسَهُ ظَلَمَا"],["الْمُولِجِ اللَّيْلَ فِي النَّهَارِ وَفِي اللَّـ","ـيْلِ نَهَارًا يُفَرِّجُ الظُّلَمَا"],["الْخَافِضِ الرَّافِعِ السَّمَاءَ عَلَى الْـ","ـأَرْضِ وَلَمْ يَبْنِ تَحْتَهَا دِعَمَا"],["الْخَالِقِ الْبَارِئِ الْمُصَوِّرِ فِي الْـ","ـأَرْحَامِ مَاءً حَتَّى يَصِيرَ دَمَا"],["وَأَنْتَ إِلَهُ الْخَلْقِ رَبِّي وَخَالِقِي","بِذَلِكَ مَا عُمِّرْتُ فِي النَّاسِ أَشْهَدُ"],["تَعَالَيْتَ رَبَّ النَّاسِ عَنْ قَوْلِ مَنْ دَعَا","سِوَاكَ إِلَهًا أَنْتَ أَعْلَى وَأَمْجَدُ"],["لَكَ الْخَلْقُ وَالنَّعْمَاءُ وَالْأَمْرُ كُلُّهُ","فَإِيَّاكَ نَسْتَهْدِي وَإِيَّاكَ نَعْبُدُ"],["إِنَّ تَقْوَى رَبِّنَا خَيْرُ نَفَلْ","وَبِإِذْنِ اللَّهِ رَيْثِي وَعَجَلْ"],["أَحْمَدُ اللَّهَ فَلَا نِدَّ لَهُ","بِيَدَيْهِ الْخَيْرُ مَا شَاءَ فَعَلْ"],["مَنْ هَدَاهُ سُبُلَ الْخَيْرِ اهْتَدَى","نَاعِمَ الْبَالِ وَمَنْ شَاءَ أَضَلّْ"],["إِلَهَنَا مَا أَعْدَلَكْ","مَلِيكَ كُلِّ مَنْ مَلَكْ"],["لَبَّيْكَ قَدْ لَبَّيْتُ لَكْ","لَبَّيْكَ إِنَّ الْحَمْدَ لَكْ"],["وَالْمُلْكَ لَا شَرِيكَ لَكْ","مَا خَابَ عَبْدٌ سَأَلَكْ"],["أَنْتَ لَهُ حَيْثُ سَلَكْ","لَوْلَاكَ يَا رَبِّي هَلَكْ"],["وَاللَّيْلُ لَمَّا أَنْ حَلَكْ","وَالسَّابِحَاتُ فِي الْفَلَكْ"],["عَلَى مَجَارِي الْمُنْسَلَكْ","كُلُّ نَبِيٍّ وَمَلَكْ"],["وَكُلُّ مَنْ أَهَلَّ لَكْ","سَبَّحَ أَوْ صَلَّى فَلَكْ"],["لَبَّيْكَ إِنَّ الْحَمْدَ لَكْ","وَالْمُلْكَ لَا شَرِيكَ لَكْ"],["لَكَ الْحَمْدُ حَمْدًا نَسْتَلِذُّ بِهِ ذِكْرَا","وَإِنْ كُنْتُ لَا أُحْصِي ثَنَاءً وَلَا شُكْرَا"],["لَكَ الْحَمْدُ حَمْدًا طَيِّبًا يَمْلَأُ السَّمَا","وَأَقْطَارَهَا وَالْأَرْضَ وَالْبَرَّ وَالْبَحْرَا"],["لَكَ الْحَمْدُ حَمْدًا سَرْمَدِيًّا مُبَارَكًا","يَقِلُّ مِدَادُ الْبَحْرِ عَنْ كُنْهِهِ حَصْرَا"],["لَكَ الْحَمْدُ مَقْرُونًا بِشُكْرِكَ دَائِمًا","لَكَ الْحَمْدُ فِي الْأُولَى لَكَ الْحَمْدُ فِي الْأُخْرَى"],["لَكَ الْحَمْدُ حَمْدًا طَيِّبًا أَنْتَ أَهْلُهُ","عَلَى كُلِّ حَالٍ يَشْمَلُ السِّرَّ وَالْجَهْرَا"],["لَكَ الْحَمْدُ حَمْدًا لَا يُعَدُّ لِحَاصِرٍ","أَيُحْصِي الْحَصَى وَالنَّبْتَ وَالرَّمْلَ وَالْقَطْرَا"],["أَرَبًّا وَاحِدًا أَمْ أَلْفَ رَبٍّ","أَدِينُ إِذَا تُقُسِّمَتِ الْأُمُورُ"],["عَزَلْتُ اللَّاتَ وَالْعُزَّى جَمِيعًا","كَذَلِكَ يَفْعَلُ الْجَلْدُ الصَّبُورُ"],["فَلَا الْعُزَّى أَدِينُ وَلَا ابْنَتَيْهَا","وَلَا صَنَمَيْ بَنِي عَمْرٍو أَزُورُ"],["وَلَا هُبَلًا أَدِينُ وَكَانَ رَبًّا","لَنَا فِي الدَّهْرِ إِذْ حِلْمِي يَسِيرُ"],["وَلَكِنْ أَعْبُدُ الرَّحْمَنَ رَبِّي","لِيَغْفِرَ ذَنْبِيَ الرَّبُّ الْغَفُورُ"],["وَأَسْلَمْتُ وَجْهِي لِمَنْ أَسْلَمَتْ","لَهُ الْأَرْضُ تَحْمِلُ صَخْرًا ثِقَالَا"],["دَحَاهَا فَلَمَّا رَآهَا اسْتَوَتْ","عَلَى الْمَاءِ أَرْسَى عَلَيْهَا الْجِبَالَا"],["وَأَسْلَمْتُ وَجْهِي لِمَنْ أَسْلَمَتْ","لَهُ الْمُزْنُ تَحْمِلُ عَذْبًا زُلَالَا"],["إِذَا هِيَ سِيقَتْ إِلَى بَلْدَةٍ","أَطَاعَتْ فَصَبَّتْ عَلَيْهَا سِجَالَا"],["إِلَهُ الْعَالَمِينَ وَكُلِّ أَرْضٍ","وَرَبُّ الرَّاسِيَاتِ مِنَ الْجِبَالِ"],["بَنَاهَا وَابْتَنَى سَبْعًا شِدَادًا","بِلَا عَمَدٍ يُرَيْنَ وَلَا رِجَالِ"],["وَسَوَّاهَا وَزَيَّنَهَا بِنُورٍ","مِنَ الشَّمْسِ الْمُضِيئَةِ وَالْهِلَالِ"],["وَمِنْ شُهُبٍ تَلَأْلَأُ فِي دُجَاهَا","مَرَامِيهَا أَشَدُّ مِنَ النِّصَالِ"],["وَشَقَّ الْأَرْضَ فَانْبَجَسَتْ عُيُونًا","وَأَنْهَارًا مِنَ الْعَذْبِ الزُّلَالِ"],["وَبَارَكَ فِي نَوَاحِيهَا وَزَكَّى","بِهَا مَا كَانَ مِنْ حَرْثٍ وَمَالِ"],["فَكُلُّ مُعَمَّرٍ لَا بُدَّ يَوْمًا","وَذِي دُنْيَا يَصِيرُ إِلَى زَوَالِ"],["وَيَفْنَى بَعْدَ جِدَّتِهِ وَيَبْلَى","سِوَى الْبَاقِي الْمُقَدَّسِ ذِي الْجَلَالِ"],["أَرَى النَّاسَ لَا يَدْرُونَ مَا قَدْرُ أَمْرِهِمْ","بَلَى كُلُّ ذِي لُبٍّ إِلَى اللَّهِ وَاسِلُ"],["أَلَا كُلُّ شَيْءٍ مَا خَلَا اللَّهَ بَاطِلُ","وَكُلُّ نَعِيمٍ لَا مَحَالَةَ زَائِلُ"],["وَكُلُّ أُنَاسٍ سَوْفَ تَدْخُلُ بَيْنَهُمْ","دُوَيْهِيَةٌ تَصْفَرُّ مِنْهَا الْأَنَامِلُ"],["وَكُلُّ امْرِئٍ يَوْمًا سَيَعْلَمُ سَعْيَهُ","إِذَا كُشِّفَتْ عِنْدَ الْإِلَهِ الْمَحَاصِلُ"],["لِلَّهِ نَافِلَةُ الْأَجَلِّ الْأَفْضَلِ","وَلَهُ الْعُلَى وَأَثِيثُ كُلِّ مُؤَثَّلِ"],["لَا يَسْتَطِيعُ النَّاسُ مَحْوَ كِتَابِهِ","أَنَّى وَلَيْسَ قَضَاؤُهُ بِمُبَدَّلِ"],["سَوَّى فَأَغْلَقَ دُونَ غُرَّةِ عَرْشِهِ","سَبْعًا طِبَاقًا فَوْقَ فَرْعِ الْمَنْقَلِ"],["وَالْأَرْضَ تَحْتَهُمُ مِهَادًا رَاسِيًا","ثَبَتَتْ خَوَالِقُهَا بِصُمِّ الْجَنْدَلِ"],["وَالْمَاءُ وَالنِّيرَانُ مِنْ آيَاتِهِ","فِيهِنَّ مَوْعِظَةٌ لِمَنْ لَمْ يَجْهَلِ"],["بَلْ كُلُّ سَعْيِكَ بَاطِلٌ إِلَّا التُّقَى","فَإِذَا انْقَضَى شَيْءٌ كَأَنْ لَمْ يُفْعَلِ"],["أَلَا إِنَّنَا كُلَّنَا بَائِدُ","وَأَيُّ بَنِي آدَمٍ خَالِدُ"],["وَبَدْؤُهُمُ كَانَ مِنْ رَبِّهِمْ","وَكُلٌّ إِلَى رَبِّهِ عَائِدُ"],["فَيَا عَجَبَا كَيْفَ يُعْصَى الْإِلَـ","ـهُ أَمْ كَيْفَ يَجْحَدُهُ الْجَاحِدُ"],["وَلِلَّهِ فِي كُلِّ تَحْرِيكَةٍ","عَلَيْنَا وَتَسْكِينَةٍ شَاهِدُ"],["وَفِي كُلِّ شَيْءٍ لَهُ آيَةٌ","تَدُلُّ عَلَى أَنَّهُ وَاحِدُ"],["تَأَمَّلْ فِي نَبَاتِ الْأَرْضِ وَانْظُرْ","إِلَى آثَارِ مَا صَنَعَ الْمَلِيكُ"],["عُيُونٌ مِنْ لُجَيْنٍ شَاخِصَاتٌ","بِأَحْدَاقٍ هِيَ الذَّهَبُ السَّبِيكُ"],["عَلَى قُضُبِ الزَّبَرْجَدِ شَاهِدَاتٌ","بِأَنَّ اللَّهَ لَيْسَ لَهُ شَرِيكُ"],["شَهِدْتُ بِأَنَّ وَعْدَ اللَّهِ حَقٌّ","وَأَنَّ النَّارَ مَثْوَى الْكَافِرِينَا"],["وَأَنَّ الْعَرْشَ فَوْقَ الْمَاءِ طَافٍ","وَفَوْقَ الْعَرْشِ رَبُّ الْعَالَمِينَا"],["وَتَحْمِلُهُ مَلَائِكَةٌ كِرَامٌ","مَلَائِكَةُ الْإِلَهِ مُسَوِّمِينَا"],["هُوَ أَوَّلٌ هُوَ آخِرٌ هُوَ ظَاهِرٌ","هُوَ بَاطِنٌ هِيَ أَرْبَعٌ بِوِزَانِ"],["مَا قَبْلَهُ شَيْءٌ كَذَا مَا بَعْدَهُ","شَيْءٌ تَعَالَى اللَّهُ ذُو السُّلْطَانِ"],["مَا فَوْقَهُ شَيْءٌ كَذَا مَا دُونَهُ","شَيْءٌ وَذَا تَفْسِيرُ ذِي الْبُرْهَانِ"],["وَهُوَ الْعَلِيُّ فَكُلُّ أَنْوَاعِ الْعُلُوِّ","لَهُ فَثَابِتَةٌ بِلَا نُكْرَانِ"],["وَهُوَ الْعَظِيمُ بِكُلِّ مَعْنًى يُوجِبُ التَّـ","ـعْظِيمَ لَا يُحْصِيهِ مِنْ إِنْسَانِ"],["وَهُوَ الْجَلِيلُ فَكُلُّ أَوْصَافِ الْجَلَاـ","ـلِ لَهُ مُحَقَّقَةٌ بِلَا بُطْلَانِ"],["وَهُوَ السَّمِيعُ يَرَى وَيَسْمَعُ كُلَّ مَا","فِي الْكَوْنِ عَالِيهِ مَعَ التَّحْتَانِي"],["وَلِكُلِّ صَوْتٍ مِنْهُ سَمْعٌ حَاضِرٌ","فَالسِّرُّ وَالْإِعْلَانُ مُسْتَوِيَانِ"],["وَالسَّمْعُ مِنْهُ وَاسِعُ الْأَصْوَاتِ لَا","يَخْفَى عَلَيْهِ بَعِيدُهَا وَالدَّانِي"],["وَهُوَ الْبَصِيرُ يَرَى دَبِيبَ النَّمْلَةِ السَّـ","ـوْدَاءِ تَحْتَ الصَّخْرِ وَالصَّوَّانِ"],["وَيَرَى مَجَارِي الْقُوتِ فِي أَعْضَائِهَا","وَيَرَى عُرُوقَ نِيَاطِهَا بِعِيَانِ"],["وَيَرَى خِيَانَاتِ الْعُيُونِ بِلَحْظِهَا","وَيَرَى كَذَاكَ تَقَلُّبَ الْأَجْفَانِ"],["وَهُوَ الْعَلِيمُ أَحَاطَ عِلْمًا بِالَّذِي","فِي الْكَوْنِ مِنْ سِرٍّ وَمِنْ إِعْلَانِ"],["وَبِكُلِّ شَيْءٍ عِلْمُهُ سُبْحَانَهُ","فَهُوَ الْمُحِيطُ وَلَيْسَ ذَا نِسْيَانِ"],["وَهُوَ الْحَمِيدُ فَكُلُّ حَمْدٍ وَاقِعٍ","أَوْ كَانَ مَفْرُوضًا مَدَى الْأَزْمَانِ"],["مَلَأَ الْوُجُودَ جَمِيعَهُ وَنَظِيرَهُ","مِنْ غَيْرِ مَا عَدٍّ وَلَا حُسْبَانِ"],["هُوَ أَهْلُهُ سُبْحَانَهُ وَبِحَمْدِهِ","كُلُّ الْمَحَامِدِ وَصْفُ ذِي الْإِحْسَانِ"],["وَهُوَ الْقَدِيرُ فَلَيْسَ يُعْجِزُهُ إِذَا","مَا رَامَ شَيْئًا قَطُّ ذُو سُلْطَانِ"],["وَهُوَ الْغَنِيُّ بِذَاتِهِ فَغِنَاهُ ذَاـ","ـتِيٌّ لَهُ كَالْجُودِ وَالْإِحْسَانِ"],["وَهُوَ الْحَلِيمُ فَلَا يُعَاجِلُ عَبْدَهُ","بِعُقُوبَةٍ لِيَتُوبَ مِنْ عِصْيَانِ"],["وَهُوَ الْعَفُوُّ فَعَفْوُهُ وَسِعَ الْوَرَى","لَوْلَاهُ غَارَ الْأَرْضُ بِالسُّكَّانِ"],["وَهُوَ الْمُجِيبُ يَقُولُ مَنْ يَدْعُو أُجِبْـ","ـهُ أَنَا الْمُجِيبُ لِكُلِّ مَنْ نَادَانِي"],["وَهُوَ الْمُجِيبُ لِدَعْوَةِ الْمُضْطَرِّ إِذْ","يَدْعُوهُ فِي سِرٍّ وَفِي إِعْلَانِ"],["وَهُوَ الْجَوَادُ فَجُودُهُ عَمَّ الْوُجُوـ","ـدَ جَمِيعَهُ بِالْفَضْلِ وَالْإِحْسَانِ"],["وَهُوَ الْجَوَادُ فَلَا يُخَيِّبُ سَائِلًا","وَلَوَ انَّهُ مِنْ أُمَّةِ الْكُفْرَانِ"],["وَهُوَ الْوَدُودُ يُحِبُّهُمْ وَيُحِبُّهُ","أَحْبَابُهُ وَالْفَضْلُ لِلْمَنَّانِ"],["وَهُوَ الَّذِي جَعَلَ الْمَحَبَّةَ فِي قُلُوـ","ـبِهِمُ وَجَازَاهُمْ بِحُبٍّ ثَانِ"],["وَهُوَ الشَّكُورُ فَلَنْ يُضَيِّعَ سَعْيَهُمْ","لَكِنْ يُضَاعِفُهُ بِلَا حُسْبَانِ"],["مَا لِلْعِبَادِ عَلَيْهِ حَقٌّ وَاجِبٌ","هُوَ أَوْجَبَ الْأَجْرَ الْعَظِيمَ الشَّأْنِ"],["كَلَّا وَلَا عَمَلٌ لَدَيْهِ ضَائِعٌ","إِنْ كَانَ بِالْإِخْلَاصِ وَالْإِحْسَانِ"],["إِنْ عُذِّبُوا فَبِعَدْلِهِ أَوْ نُعِّمُوا","فَبِفَضْلِهِ سُبْحَانَ ذِي السُّلْطَانِ"],["وَهُوَ الْغَفُورُ فَلَوْ أَتَى بِقُرَابِهَا","خَطَأً مُوَحِّدُ رَبِّهِ الرَّحْمَنِ"],["لَأَتَاهُ بِالْغُفْرَانِ مِلْءَ قُرَابِهَا","سُبْحَانَهُ هُوَ وَاسِعُ الْغُفْرَانِ"],["مَا شِئْتَ كَانَ وَإِنْ لَمْ أَشَأْ","وَمَا شِئْتُ إِنْ لَمْ تَشَأْ لَمْ يَكُنْ"],["خَلَقْتَ الْعِبَادَ عَلَى مَا عَلِمْتَ","فَفِي الْعِلْمِ يَجْرِي الْفَتَى وَالْمُسِنْ"],["فَمِنْهُمْ شَقِيٌّ وَمِنْهُمْ سَعِيدٌ","وَمِنْهُمْ قَبِيحٌ وَمِنْهُمْ حَسَنْ"],["عَلَى ذَا مَنَنْتَ وَهَذَا خَذَلْتَ","وَهَذَا أَعَنْتَ وَذَا لَمْ تُعِنْ"],["يَا مَنْ يَرَى مَدَّ الْبَعُوضِ جَنَاحَهَا","فِي ظُلْمَةِ اللَّيْلِ الْبَهِيمِ الْأَلْيَلِ"],["وَيَرَى عُرُوقَ نِيَاطِهَا فِي نَحْرِهَا","وَالْمُخَّ فِي تِلْكَ الْعِظَامِ النُّحَّلِ"],["اغْفِرْ لِعَبْدٍ تَابَ مِنْ فَرَطَاتِهِ","مَا كَانَ مِنْهُ فِي الزَّمَانِ الْأَوَّلِ"],["سُبْحَانَ مَنْ يُعْطِي الْمُنَى بِخَوَاطِرٍ","فِي النَّفْسِ لَمْ يَنْطِقْ بِهِنَّ لِسَانُ"],["سُبْحَانَ مَنْ لَا شَيْءَ يَحْجُبُ عِلْمَهُ","فَالسِّرُّ أَجْمَعُ عِنْدَهُ إِعْلَانُ"],["سُبْحَانَ مَنْ هُوَ لَا يَزَالُ مُسَبَّحًا","أَبَدًا وَلَيْسَ لِغَيْرِهِ السُّبْحَانُ"],["سُبْحَانَ مَنْ تَجْرِي قَضَايَاهُ عَلَى","مَا شَاءَ مِنْهَا غَائِبٌ وَعِيَانُ"],["سُبْحَانَ مَنْ هُوَ لَا يَزَالُ وَرِزْقُهُ","لِلْعَالَمِينَ بِهِ عَلَيْهِ ضَمَانُ"],["سُبْحَانَ مَنْ فِي ذِكْرِهِ طُرُقُ الرِّضَى","مِنْهُ وَفِيهِ الرَّوْحُ وَالرَّيْحَانُ"],["مَلِكٌ عَزِيزٌ لَا يُفَارِقُ عِزُّهُ","يُعْصَى وَيُرْجَى عِنْدَهُ الْغُفْرَانُ"],["إِذَا مَا خَلَوْتَ الدَّهْرَ يَوْمًا فَلَا تَقُلْ","خَلَوْتُ وَلَكِنْ قُلْ عَلَيَّ رَقِيبُ"],["وَلَا تَحْسَبَنَّ اللَّهَ يَغْفَلُ سَاعَةً","وَلَا أَنَّ مَا يَخْفَى عَلَيْهِ يَغِيبُ"],["إِذَا كَانَ شُكْرِي نِعْمَةَ اللَّهِ نِعْمَةً","عَلَيَّ لَهُ فِي مِثْلِهَا يَجِبُ الشُّكْرُ"],["فَكَيْفَ بُلُوغُ الشُّكْرِ إِلَّا بِفَضْلِهِ","وَإِنْ طَالَتِ الْأَيَّامُ وَاتَّصَلَ الْعُمْرُ"],["إِذَا مَسَّ بِالسَّرَّاءِ عَمَّ سُرُورُهَا","وَإِنْ مَسَّ بِالضَّرَّاءِ أَعْقَبَهَا الْأَجْرُ"],["وَمَا مِنْهُمَا إِلَّا لَهُ فِيهِ نِعْمَةٌ","تَضِيقُ بِهَا الْأَوْهَامُ وَالْبَرُّ وَالْبَحْرُ"],["يَا رَبِّ أَنْتَ خَلَقْتَنِي","وَخَلَقْتَ لِي وَخَلَقْتَ مِنِّي"],["سُبْحَانَكَ اللَّهُمَّ عَاـ","ـلِمَ كُلِّ غَيْبٍ مُسْتَكِنِّ"],["مَا لِي بِشُكْرِكَ طَاقَةٌ","يَا سَيِّدِي إِنْ لَمْ تُعِنِّي"],["قَلْبِي بِرَحْمَتِكَ اللَّهُمَّ ذُو أُنُسِ","فِي السِّرِّ وَالْجَهْرِ وَالْإِصْبَاحِ وَالْغَلَسِ"],["وَمَا تَقَلَّبْتُ مِنْ نَوْمِي وَفِي سِنَتِي","إِلَّا وَذِكْرُكَ بَيْنَ النَّفْسِ وَالنَّفَسِ"],["لَقَدْ مَنَنْتَ عَلَى قَلْبِي بِمَعْرِفَةٍ","بِأَنَّكَ اللَّهُ ذُو الْآلَاءِ وَالْقُدُسِ"],["لَكَ الْحَمْدُ يَا ذَا الْجُودِ وَالْمَجْدِ وَالْعُلَا","تَبَارَكْتَ تُعْطِي مَنْ تَشَاءُ وَتَمْنَعُ"],["إِلَهِي وَخَلَّاقِي وَحِرْزِي وَمَوْئِلِي","إِلَيْكَ لَدَى الْإِعْسَارِ وَالْيُسْرِ أَفْزَعُ"],["إِلَهِي لَئِنْ جَلَّتْ وَجَمَّتْ خَطِيئَتِي","فَعَفْوُكَ عَنْ ذَنْبِي أَجَلُّ وَأَوْسَعُ"],["إِلَهِي تَرَى حَالِي وَفَقْرِي وَفَاقَتِي","وَأَنْتَ مُنَاجَاتِي الْخَفِيَّةَ تَسْمَعُ"],["إِلَهِي فَلَا تَقْطَعْ رَجَائِي وَلَا تُزِغْ","فُؤَادِي فَلِي فِي سَيْبِ جُودِكَ مَطْمَعُ"],["إِلَهِي لَئِنْ خَيَّبْتَنِي أَوْ طَرَدْتَنِي","فَمَنْ ذَا الَّذِي أَرْجُو وَمَنْ لِيَ يَشْفَعُ"],["إِلَهِي أَجِرْنِي مِنْ عَذَابِكَ إِنَّنِي","أَسِيرٌ ذَلِيلٌ خَائِفٌ لَكَ أَخْضَعُ"],["إِلَهِي لَئِنْ عَذَّبْتَنِي أَلْفَ حِجَّةٍ","فَحَبْلُ رَجَائِي مِنْكَ لَا يَتَقَطَّعُ"],["إِلَهِي إِذَا لَمْ تَرْعَنِي كُنْتُ ضَائِعًا","وَإِنْ كُنْتَ تَرْعَانِي فَلَسْتُ أُضَيَّعُ"],["إِلَهِي ذُنُوبِي جَازَتِ الطَّوْدَ وَاعْتَلَتْ","وَصَفْحُكَ عَنْ ذَنْبِي أَجَلُّ وَأَرْفَعُ"],["إِلَهِي أَنِلْنِي مِنْكَ رُوحًا وَرَحْمَةً","فَلَسْتُ سِوَى أَبْوَابِ فَضْلِكَ أَقْرَعُ"],["أَيَا مَنْ لَيْسَ لِي مِنْهُ مُجِيرُ","بِعَفْوِكَ مِنْ عَذَابِكَ أَسْتَجِيرُ"],["أَنَا الْعَبْدُ الْمُقِرُّ بِكُلِّ ذَنْبٍ","وَأَنْتَ السَّيِّدُ الْمَوْلَى الْغَفُورُ"],["فَإِنْ عَذَّبْتَنِي فَبِسُوءِ فِعْلِي","وَإِنْ تَغْفِرْ فَأَنْتَ بِهِ جَدِيرُ"],["أَفِرُّ إِلَيْكَ مِنْكَ وَأَيْنَ إِلَّا","إِلَيْكَ يَفِرُّ مِنْكَ الْمُسْتَجِيرُ"],["أَنَا الْفَقِيرُ إِلَى رَبِّ الْبَرِيَّاتِ","أَنَا الْمُسَيْكِينُ فِي مَجْمُوعِ حَالَاتِي"],["أَنَا الظَّلُومُ لِنَفْسِي وَهْيَ ظَالِمَتِي","وَالْخَيْرُ إِنْ يَأْتِنَا مِنْ عِنْدِهِ يَأْتِي"],["لَا أَسْتَطِيعُ لِنَفْسِي جَلْبَ مَنْفَعَةٍ","وَلَا عَنِ النَّفْسِ فِي دَفْعِ الْمَضَرَّاتِ"],["وَلَيْسَ لِي دُونَهُ مَوْلًى يُدَبِّرُنِي","وَلَا شَفِيعٌ إِلَى رَبِّ السَّمَاوَاتِ"],["وَلَسْتُ أَمْلِكُ شَيْئًا دُونَهُ أَبَدًا","وَلَا شَرِيكٌ أَنَا فِي بَعْضِ ذَرَّاتِ"],["وَلَا ظَهِيرَ لَهُ كَيْ أَسْتَعِينَ بِهِ","كَمَا يَكُونُ لِأَرْبَابِ الْوِلَايَاتِ"],["إِذَا اشْتَمَلَتْ عَلَى الْيَأْسِ الْقُلُوبُ","وَضَاقَ لِمَا بِهَا الصَّدْرُ الرَّحِيبُ"],["وَأَوْطَنَتِ الْمَكَارِهُ وَاطْمَأَنَّتْ","وَأَرْسَتْ فِي أَمَاكِنِهَا الْخُطُوبُ"],["وَلَمْ تَرَ لِانْكِشَافِ الضُّرِّ وَجْهًا","وَلَا أَغْنَى بِحِيلَتِهِ الْأَرِيبُ"],["أَتَاكَ عَلَى قُنُوطٍ مِنْكَ غَوْثٌ","يَمُنُّ بِهِ اللَّطِيفُ الْمُسْتَجِيبُ"],["وَكُلُّ الْحَادِثَاتِ إِذَا تَنَاهَتْ","فَمَوْصُولٌ بِهَا الْفَرَجُ الْقَرِيبُ"],["وَكَمْ لِلَّهِ مِنْ لُطْفٍ خَفِيٍّ","يَدِقُّ خَفَاهُ عَنْ فَهْمِ الذَّكِيِّ"],["وَكَمْ يُسْرٍ أَتَى مِنْ بَعْدِ عُسْرٍ","فَفَرَّجَ كُرْبَةَ الْقَلْبِ الشَّجِيِّ"],["وَكَمْ أَمْرٍ تُسَاءُ بِهِ صَبَاحًا","وَتَأْتِيكَ الْمَسَرَّةُ بِالْعَشِيِّ"],["إِذَا ضَاقَتْ بِكَ الْأَحْوَالُ يَوْمًا","فَثِقْ بِالْوَاحِدِ الْفَرْدِ الْعَلِيِّ"],["وَلَا تَجْزَعْ إِذَا مَا نَابَ خَطْبٌ","فَكَمْ لِلَّهِ مِنْ لُطْفٍ خَفِيِّ"],["ذُنُوبِيَ إِنْ فَكَّرْتُ فِيهَا كَثِيرَةٌ","وَرَحْمَةُ رَبِّي مِنْ ذُنُوبِيَ أَوْسَعُ"],["فَمَا طَمَعِي فِي صَالِحٍ قَدْ عَمِلْتُهُ","وَلَكِنَّنِي فِي رَحْمَةِ اللَّهِ أَطْمَعُ"],["مَلِيكِي وَمَوْلَائِي وَرَبِّي وَحَافِظِي","وَإِنِّي لَهُ عَبْدٌ أُقِرُّ وَأَخْضَعُ"]],"secs":{"1":"في الحمد والتمجيد — أمية بن أبي الصلت: لك الحمد والنعماء والملك ربنا","13":"في الحمد والتمجيد — أمية بن أبي الصلت: مجدوا الله فهو للمجد أهل","16":"في الحمد والتمجيد — زيد بن عمرو بن نفيل: إلى الله أهدي مدحتي وثنائيا","29":"في الحمد والتمجيد — المنسوب إلى ورقة بن نوفل: سبحان ذي العرش سبحانًا يدوم له","33":"في الحمد والتمجيد — النابغة الجعدي: الحمد لله لا شريك له","37":"في الحمد والتمجيد — حسان بن ثابت: وأنت إله الخلق ربي وخالقي","40":"في الحمد والتمجيد — لبيد بن ربيعة: إن تقوى ربنا خير نفل","43":"في الحمد والتمجيد — أبو نواس: إلهنا ما أعدلك","51":"في الحمد والتمجيد — عبد الرحيم البرعي: لك الحمد حمدًا نستلذ به ذكرا","57":"في التوحيد ودلائل القدرة — زيد بن عمرو بن نفيل: أربًّا واحدًا أم ألف رب","62":"في التوحيد ودلائل القدرة — زيد بن عمرو بن نفيل: وأسلمت وجهي لمن أسلمت","66":"في التوحيد ودلائل القدرة — أمية بن أبي الصلت: إله العالمين وكل أرض","74":"في التوحيد ودلائل القدرة — لبيد بن ربيعة: ألا كل شيء ما خلا الله باطل","78":"في التوحيد ودلائل القدرة — لبيد بن ربيعة: لله نافلة الأجل الأفضل","84":"في التوحيد ودلائل القدرة — أبو العتاهية: ألا إننا كلنا بائد","89":"في التوحيد ودلائل القدرة — أبو نواس: تأمل في نبات الأرض وانظر","92":"في التوحيد ودلائل القدرة — عبد الله بن رواحة: شهدت بأن وعد الله حق","95":"في الأسماء والصفات — ابن القيم: هو أول هو آخر هو ظاهر (من النونية)","128":"في الأسماء والصفات — الشافعي: ما شئت كان وإن لم أشأ","132":"في الأسماء والصفات — المنسوب إلى الزمخشري: يا من يرى مد البعوض جناحها","135":"في الأسماء والصفات — أبو العتاهية: سبحان من يعطي المنى بخواطر","142":"في الأسماء والصفات — أبو العتاهية: إذا ما خلوت الدهر يومًا فلا تقل","144":"في الآلاء والنعم — محمود الوراق: إذا كان شكري نعمة الله نعمة","148":"في الآلاء والنعم — أبو العتاهية: يا رب أنت خلقتني","151":"في الآلاء والنعم — المنسوب إلى الشافعي: قلبي برحمتك اللهم ذو أنس","154":"في المناجاة والافتقار — المنسوب إلى علي بن أبي طالب: لك الحمد يا ذا الجود والمجد والعلا","165":"في المناجاة والافتقار — أبو نواس: أيا من ليس لي منه مجير","169":"في المناجاة والافتقار — ابن تيمية: أنا الفقير إلى رب البريات","175":"في الرجاء وحسن الظن — المنسوب إلى علي بن أبي طالب: إذا اشتملت على اليأس القلوب","180":"في الرجاء وحسن الظن — المنسوب إلى علي بن أبي طالب: وكم لله من لطف خفي","185":"في الرجاء وحسن الظن — المنسوب إلى علي بن أبي طالب: ذنوبي إن فكرت فيها كثيرة"}}],"sharh":false};
